I'll create a React error boundary component with fallback UI, retry functionality, and error logging.

## ErrorBoundary Component

**`src/components/ErrorBoundary.tsx`**

```tsx
import React, { Component, ErrorInfo, ReactNode } from "react";

interface Props {
  children: ReactNode;
  fallback?: (error: Error, reset: () => void) => ReactNode;
  onError?: (error: Error, errorInfo: ErrorInfo) => void;
}

interface State {
  error: Error | null;
}

export class ErrorBoundary extends Component<Props, State> {
  state: State = { error: null };

  static getDerivedStateFromError(error: Error): State {
    return { error };
  }

  componentDidCatch(error: Error, errorInfo: ErrorInfo) {
    console.error("[ErrorBoundary] Uncaught render error:", {
      message: error.message,
      stack: error.stack,
      componentStack: errorInfo.componentStack,
    });
    this.props.onError?.(error, errorInfo);
  }

  reset = () => this.setState({ error: null });

  render() {
    const { error } = this.state;
    if (!error) return this.props.children;

    if (this.props.fallback) return this.props.fallback(error, this.reset);

    return <DefaultFallback error={error} reset={this.reset} />;
  }
}

function DefaultFallback({ error, reset }: { error: Error; reset: () => void }) {
  return (
    <div role="alert" style={styles.container}>
      <h2 style={styles.heading}>Something went wrong</h2>
      <pre style={styles.message}>{error.message}</pre>
      <button onClick={reset} style={styles.button}>
        Try again
      </button>
    </div>
  );
}

const styles: Record<string, React.CSSProperties> = {
  container: {
    padding: "2rem",
    border: "1px solid #f87171",
    borderRadius: "0.5rem",
    backgroundColor: "#fef2f2",
    color: "#991b1b",
    fontFamily: "sans-serif",
    maxWidth: "480px",
    margin: "2rem auto",
  },
  heading: { margin: "0 0 0.75rem", fontSize: "1.125rem" },
  message: {
    background: "#fee2e2",
    padding: "0.75rem",
    borderRadius: "0.25rem",
    fontSize: "0.875rem",
    overflowX: "auto",
    whiteSpace: "pre-wrap",
    wordBreak: "break-word",
  },
  button: {
    marginTop: "1rem",
    padding: "0.5rem 1.25rem",
    background: "#dc2626",
    color: "#fff",
    border: "none",
    borderRadius: "0.375rem",
    cursor: "pointer",
    fontSize: "0.875rem",
  },
};
```

---

### Usage

**Basic — default fallback UI:**
```tsx
<ErrorBoundary>
  <MyComponent />
</ErrorBoundary>
```

**Custom fallback UI:**
```tsx
<ErrorBoundary
  fallback={(error, retry) => (
    <div>
      <p>Oops: {error.message}</p>
      <button onClick={retry}>Retry</button>
    </div>
  )}
>
  <MyComponent />
</ErrorBoundary>
```

**With external error reporting (e.g. Sentry):**
```tsx
<ErrorBoundary onError={(error, info) => Sentry.captureException(error, { extra: info })}>
  <MyComponent />
</ErrorBoundary>
```

---

### Key design decisions

| Decision | Rationale |
|---|---|
| Class component | `getDerivedStateFromError` / `componentDidCatch` have no hook equivalents |
| `reset` clears `error` state | Re-renders children fresh; works as long as the underlying bug is transient |
| `onError` prop | Decouples logging from the component — caller decides Sentry vs console |
| Custom `fallback` render prop | Gives full UI control without subclassing |
| `role="alert"` on default fallback | Screen readers announce the error immediately |
